from taf.ul.trs_e2e_fw.lib.log_scrambling.capsv.output_parser import CapsScriptOutputParser

logger = BackgroundLogger.Instance()


class CapsInterface:
    def __init__(self):
        caps_script_filepath = os.path.join(os.path.dirname(__file__), "CAPSCLI.py")
        self._python_executable_filepath = self._get_running_python_executable_filepath()
        self._caps_script_filepath = self._get_caps_script_full_filepath(caps_script_filepath)
        self._caps_script_token_filepath = self._get_caps_token_full_filepath()
        self.caps_script_call = CapsScriptCliCallFormatter(self._python_executable_filepath,
                                                           self._caps_script_filepath, self._caps_script_token_filepath)
        self._caps_script_output_parser = CapsScriptOutputParser
        self._cli_call_results_template = collections.namedtuple("CliCallResults", ["exit_code", "raw_output"])
        self._CAPS_DL_ENC_FILE_INFO = collections.namedtuple("CapsDlEncFileInfo", "archive_filepath decryption_key")

        self._caps_script_call_results_template = collections.namedtuple("CapsScriptCallResults", ["exit_code",
                                                                                                   "raw_output",
                                                                                                   "parsed_fields"])
        self.__cli_executor = functools.partial(subprocess.check_output, stderr=subprocess.STDOUT, shell=True)

    def upload_file_to_caps(self, file, **kwargs):
        """

        """
        config_parameter = get_config_variable([kwargs.pop("config_file", "caps_qa_config")])

        config_file = self._create_config_file(config_parameter)

        if not os.path.isfile(file):
            raise IOError("Filepath '{}' doesn't".format(file) + "point to an existing regular file.")
        archive_filepath = os.path.abspath(file)

        caps_upload_call = self.caps_script_call.create_caps_upload_call(archive_filepath, config_file)

        cli_call_results = self._call_cli_executor(caps_upload_call)
        logger.debug("CLI Result :: {}".format(cli_call_results))
        if cli_call_results.exit_code != 0:
            raise Exception("Failed during Upload operation :: {}".format(cli_call_results.raw_output))

        parsed_output_fields = self._caps_script_output_parser.parse_caps_upload_output(cli_call_results.exit_code,
                                                                                        cli_call_results.raw_output)

        final_parsed = self._caps_script_call_results_template(cli_call_results.exit_code, cli_call_results.raw_output,
                                                               parsed_output_fields)

        return final_parsed.parsed_fields["attach_id"]

    def download_scrambled_file(self, attach_id, **kwargs):
        """

        """
        config_file = kwargs.pop("config_file", "caps_qa_config")
        destination_dirpath = kwargs.pop("destination_dirpath", "execution_logs/")

        output_match = self._wait_for_ready_state(attach_id=attach_id, config_file=config_file)

        logger.info("#### Downloading {} from capsv".format(output_match.parsed_fields["scrambled_filename"]))

        filename = output_match.parsed_fields["scrambled_filename"]

        caps_download_call = self.caps_script_call.create_caps_download_call(
            attach_id, download_destination_dirpath=destination_dirpath, download_target_filenames=filename)

        logger.info("Download Command {}".format(caps_download_call))

        cli_call_result = self._call_cli_executor(caps_download_call)

        parsed_output_fields = self._caps_script_output_parser.parse_caps_download_output(cli_call_result.exit_code,
                                                                                          cli_call_result.raw_output)

        logger.info("#### PARSED output fields are {}".format(parsed_output_fields))

        final_parsed = self._caps_script_call_results_template(cli_call_result.exit_code, cli_call_result.raw_output,
                                                               parsed_output_fields)

        downloaded_encrypted_full_filepath = destination_dirpath + filename

        scrambling_data = self._CAPS_DL_ENC_FILE_INFO(downloaded_encrypted_full_filepath,
                                                      final_parsed.parsed_fields["decryption_key"])

        password, filepath = scrambling_data.decryption_key, scrambling_data.archive_filepath

        unzip_command = "7z x {0} -o{1} -p{2} && rm {0}".format(filepath, filename, password)
        unizip_output = self._call_cli_executor(unzip_command)
        destination_dirpath = os.path.abspath(filepath.rsplit("/", 1)[0]+"/execution_logs/") # +"/execution_logs/")
        logger.info("### unzip output is {}".format(unizip_output))
        if not os.path.exists(destination_dirpath):
            os.makedirs(destination_dirpath)
        copy_command = "cp -r {0} {1}".format(filename,destination_dirpath) # && rm -r {0}
        self._call_cli_executor(copy_command)

        if "/" not in filename:
            expected_output = [destination_dirpath , filename, password]
            return expected_output
        else:
            expected_output = [os.path.abspath(filename + "/scrambled.zip"), password]
            return expected_output

    def download_encrypted_file(self, attach_id, **kwargs):
        """

        """
        config_file = kwargs.pop("config_file", "caps_qa_config")
        destination_dirpath = kwargs.pop("destination_dirpath", "execution_logs/")

        output_match = self._wait_for_ready_state(attach_id=attach_id, config_file=config_file)

        logger.info("#### Downloading {} from capsv".format(output_match.parsed_fields["encrypted_filename"]))

        filename = output_match.parsed_fields["encrypted_filename"]

        caps_download_call = self.caps_script_call.create_caps_download_call(
            attach_id, download_destination_dirpath=destination_dirpath, download_target_filenames=filename)

        logger.info("Download Command {}".format(caps_download_call))

        cli_call_result = self._call_cli_executor(caps_download_call)

        parsed_output_fields = self._caps_script_output_parser.parse_caps_download_output(cli_call_result.exit_code,
                                                                                          cli_call_result.raw_output)

        logger.info("#### PARSED output fields are {}".format(parsed_output_fields))

        final_parsed = self._caps_script_call_results_template(cli_call_result.exit_code, cli_call_result.raw_output,
                                                               parsed_output_fields)

        downloaded_encrypted_full_filepath = destination_dirpath + filename

        scrambling_data = self._CAPS_DL_ENC_FILE_INFO(downloaded_encrypted_full_filepath,
                                                      final_parsed.parsed_fields["decryption_key"])

        password, filepath = scrambling_data.decryption_key, scrambling_data.archive_filepath

        unzip_command = "7z x {0} -o{1} -p{2} && rm {0}".format(filepath, filename, password)
        unizip_output = self._call_cli_executor(unzip_command)

        logger.info("### unzip output is {}".format(unizip_output))

        if "/" not in filename:
            return os.path.abspath(filepath.rsplit("/", 1)[0] + "/" + filename + "/encrypted.zip")
        else:
            return os.path.abspath(filename + "/encrypted.zip")

    def list_caps_attachment(self, attach_id, **kwargs):
        """

        """
        config_parameter = get_config_variable([kwargs.pop("config_file", "caps_qa_config")])

        config_file = self._create_config_file(config_parameter)

        caps_list_call = self.caps_script_call.create_caps_list_call(attach_id=attach_id, config_file=config_file)

        logger.info("CAPS list command {}".format(caps_list_call))

        cli_call_results = self._call_cli_executor(caps_list_call)

        logger.info("CAPS list output {}".format(cli_call_results))

        parsed_output_fields = self._caps_script_output_parser.parse_caps_list_output(cli_call_results.exit_code,
                                                                                      cli_call_results.raw_output)

        logger.info("CAPS list parsed {}".format(parsed_output_fields))

        return self._caps_script_call_results_template(cli_call_results.exit_code, cli_call_results.raw_output,
                                                       parsed_output_fields)

    def delete_caps_attachment(self, attach_id, **kwargs):
        config_parameter = get_config_variable([kwargs.pop("config_file", "caps_qa_config")])

        config_file = self._create_config_file(config_parameter)

        caps_del_call = self.caps_script_call.create_caps_delete_call(attach_id=attach_id, config_file=config_file)

        logger.info("Delete command {}".format(caps_del_call))

        cli_call_results = self._call_cli_executor(caps_del_call)

        logger.info("Delete output {}".format(cli_call_results))

        parsed_output_fields = self._caps_script_output_parser.parse_caps_delete_output(cli_call_results.exit_code,
                                                                                        cli_call_results.raw_output)

        return self._caps_script_call_results_template(cli_call_results.exit_code, cli_call_results.raw_output,
                                                       parsed_output_fields)

    def _wait_for_ready_state(self, attach_id, config_file):
        status_ready = False
        while not status_ready:
            caps_list_result = self.list_caps_attachment(attach_id=attach_id, config_file=config_file)
            if caps_list_result.parsed_fields["scrambled_status"] == "ready":
                return caps_list_result
            else:
                sleep(30)

    def _get_running_python_executable_filepath(self):
        """
        Return full filepath to currently running Python's executable if it
        can be located, otherwise raise exception.

        :return: string filepath to executable of Python interpreter currently running
                 this function.

        :raises IOError: raised when function was unable to determine full filepath to
                         the executable of Python interpreter currently running this
                         function.
        """
        if not sys.executable:
            raise IOError("Currently running Python interpreter wasn't able to " +
                          "determine full filepath to its executable.\n\n" +
                          "Please check issues related to `sys.executable` for some " +
                          "suggestions on how to proceed.")

        return sys.executable

    def _get_caps_script_full_filepath(self, caps_script_filepath):
        """
        Check whether CAPS script filepath points to valid file.

        :param caps_script_filepath: string containing filepath to requested CAPS
                                     script file.

        :return: string with full filepath to requested CAPS script file.

        :raises IOError: raised when `caps_script_filepath` doesn't point to
                         valid CAPS script file.
        """
        caps_script_abspath = os.path.abspath(caps_script_filepath)

        if not os.path.isfile(caps_script_abspath):
            raise IOError("Input CAPS script filepath '{}'".format(caps_script_abspath) +
                          "doesn't point to a valid file.")

        return caps_script_abspath

    def _get_caps_token_full_filepath(self):
        """
        Return full filepath to CAPS token file.

        :return: full filepath string to CAPS token file.
        """

        caps_token_filepath = os.path.join(os.path.join(ConfigHandler.config['common_resources_path']), "token")

        if not os.path.isfile(caps_token_filepath):
            raise IOError("CAPS token filepath '{}'".format(caps_token_filepath) +
                          "doesn't point to a valid file.")

        return caps_token_filepath

    def _call_cli_executor(self, cli_call):
        """
        Run CLI call in CLI executor, wait until completion and return
        exit code and generated output stream contents.

        :param cli_call: string with prepared (formatted) CLI call to be run.

        :return: tuple containing returned exit code and generated output stream
                 contents.
        """
        try:
            logger.info("Executing {}. This will take some time, please wait until completion")
            cli_call_results = self._cli_call_results_template(0, self.__cli_executor(cli_call))
        except subprocess.CalledProcessError as cpe_exc:
            cli_call_results = self._cli_call_results_template(cpe_exc.returncode, cpe_exc.output)

        return cli_call_results

    def _create_config_file(self, config_parameter):
        caps_config_path = "execution_logs/caps_config_file.config"

        if os.path.isfile(caps_config_path):
            logger.info("###### Config file already created ######")
            return caps_config_path

        logger.info("###### Creating config file ######")
        config = configparser.ConfigParser()
        config.add_section('Defaults')
        for key, value in config_parameter.items():
            config.set('Defaults', key, value)

        with open(caps_config_path, 'w') as caps_config:
            config.write(caps_config)
        return caps_config_path

    def _search_ips_in_files(self, folder_path):
        ip_list = []

        ipv4_pattern = r'\b(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\b'
        ipv6_pattern =r'\b(?:[0-9a-fA-F]{0,4}:){6}[0-9a-fA-F]{0,4}\b'

        find_command = 'grep -r -Eo "{}|{}" {}'.format(ipv4_pattern,ipv6_pattern,folder_path)
        result = subprocess.Popen(find_command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = result.communicate()
        stdout = stdout.decode('utf-8')

        for line in stdout.splitlines():
            ipv4_matches = self._extract_ipv4_ips(line)
            for ipv4 in ipv4_matches:
                ipv4_str = '.'.join(ipv4)  # Convert the tuple to a string
                ipv4_str = ipv4_str.encode('utf-8').decode('utf-8')  # Convert to regular string
                if ipv4_str.startswith('10.'): #or ipv4_str.startswith('172.') or ipv4_str.startswith('192.168.'):
                    ip_list.append(line)

        return self._find_ipv6_addresses_in_folder(folder_path, ip_list)

    def _extract_ipv4_ips(self, text):
        ipv4_pattern =r'\b(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\b'
        #ipv6_pattern =r'\b(?:[0-9a-fA-F]{0,4}:){6}[0-9a-fA-F]{0,4}\b'

        ipv4_matches = re.findall(ipv4_pattern, text)
        #ipv6_matches = re.findall(ipv6_pattern, text, re.IGNORECASE)

        return ipv4_matches #, ipv6_matches

    def _find_ipv6_addresses_in_folder(self, folder_path, ip_list):
        ipv6_pattern = r'\b(?:[0-9a-fA-F]{0,4}:){6}[0-9a-fA-F]{0,4}\b'

        for root, dirs, files in os.walk(folder_path):
            for file in files:
                file_path = os.path.join(root, file)

                # Check if the file is a text file (you may need to extend this check for other file types)
                if file_path.endswith('.txt') or file_path.endswith('.conf') or file_path.endswith('.log'):
                    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                        file_content = f.read()
                        matches = re.findall(ipv6_pattern, str(file_content))
                        for ipv6 in matches:
                            ipv6_str = ipv6  # IPv6 addresses are already strings
                            ipv6_str = ipv6.encode('utf-8').decode('utf-8')  # Convert to regular string
                            if ipv6_str.startswith('2a00:'):
                                ip_list.append(file_path+":"+str(ipv6_str))
        return ip_list

    def _extract_nested_zips(self, root_dir, pwd):
        for foldername, subfolders, filenames in os.walk(root_dir):
            for filename in filenames:
                if filename.lower().endswith('.zip'):
                    zip_path = os.path.join(foldername, filename)
                    output_folder = os.path.splitext(zip_path)[0]  # Remove the '.zip' extension
                    with pyzipper.AESZipFile(zip_path) as zf:
                    # Set the password for decryption (if the ZIP file is encrypted)
                        zf.setpassword(pwd=str.encode(pwd))
                    # Extract all contents to the output folder
                        zf.extractall(output_folder)

    def verify_scrambling(self, **kwargs):
        actual_zip = kwargs.get("actual_zip")
        scrambled_zip = kwargs.get("scrambled_zip")
        outer_zip_path = kwargs.get("folder_path")
        pwd = kwargs.get("pwd")
        logger.info("Unzipping the compressed folders, will take few minutes")
        for i in range(4):
            self._extract_nested_zips(outer_zip_path,pwd)
        decompress_command = 'find {}  -type f -name "*.xz" -exec xz -d {{}} \;'.format(outer_zip_path)
        decompress_out=subprocess.Popen(decompress_command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        decompress_out.wait()
        logger.info("Extracting the required patterns from folder")
        ips_actual = self._search_ips_in_files(os.path.join(outer_zip_path,os.path.splitext(actual_zip)[0]))
        ips_scrambled = self._search_ips_in_files(os.path.join(outer_zip_path,os.path.splitext(scrambled_zip)[0]))
        result=[]
        logger.debug("Extraction is complete")
        for ipA in ips_scrambled:
            for ipB in  ips_actual:
                if ( "/".join(ipA.split("/")[-3:]) == "/".join(ipB.split("/")[-3:])):
                    if ipA not in result:
                        result.append(ipA)
        if not result:
            logger.info("There are no IPs similiar in Actual and Scrambled folder")
        else:
            for x in result:
                logger.info("unscrabled file: {}".format(x))
            raise Exception("Failed :: there are unscrambled ips in the folder")
            #BuiltIn().fail("Fail :: there are unscrambled ips in the folder")
